/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';
import apiFetch from '@wordpress/api-fetch';
import { Page, getAdminThemeColors } from '@wordpress/admin-ui';
import { Button, SnackbarList } from '@wordpress/components';
import { store as coreStore } from '@wordpress/core-data';
import { useDispatch, useSelect } from '@wordpress/data';
import { DataForm } from '@wordpress/dataviews/wp';
import { useCallback, useEffect, useMemo, useState } from '@wordpress/element';
import { store as noticesStore } from '@wordpress/notices';
import { ThemeProvider } from '@wordpress/theme';
import { Stack, useEnableWpCompatOverlaySlot } from '@wordpress/ui';

/**
 * Internal dependencies
 */
import PostTypesControl from './post-types-control';
import StatusCard from './status-card';

const POST_TYPES = 'site_word_counter_post_types';
const DISABLE_ANIMATION = 'site_word_counter_disable_animation';

const postTypeOptions = window.siteWordCounterSettings?.postTypes ?? [];

const fields = [
	{
		id: POST_TYPES,
		type: 'array',
		label: __( 'Count words in', 'site-word-counter' ),
		elements: postTypeOptions,
		Edit: PostTypesControl,
	},
	{
		id: DISABLE_ANIMATION,
		type: 'boolean',
		label: __(
			'Turn off counter animations across the site',
			'site-word-counter'
		),
		description: __(
			'Every counter shows its final number right away, whatever its block setting says. Visitors who ask their device for reduced motion never see the animation either way.',
			'site-word-counter'
		),
		Edit: 'toggle',
	},
];

const form = {
	layout: { type: 'regular', labelPosition: 'top' },
	fields: [
		{
			id: 'what-counts',
			label: __( 'What counts', 'site-word-counter' ),
			children: [ POST_TYPES ],
			layout: { type: 'card', isCollapsible: false },
		},
		{
			id: 'display',
			label: __( 'Display', 'site-word-counter' ),
			children: [ DISABLE_ANIMATION ],
			layout: { type: 'card', isCollapsible: false },
		},
	],
};

function Notices() {
	const notices = useSelect(
		( select ) =>
			select( noticesStore )
				.getNotices()
				.filter( ( notice ) => notice.type === 'snackbar' ),
		[]
	);
	const { removeNotice } = useDispatch( noticesStore );

	return (
		<SnackbarList
			className="site-word-counter-settings__snackbars"
			notices={ notices }
			onRemove={ removeNotice }
		/>
	);
}

export default function SettingsPage() {
	useEnableWpCompatOverlaySlot();

	const themeColors = useMemo( () => getAdminThemeColors(), [] );
	const [ status, setStatus ] = useState( null );

	const { settings, hasEdits, isSaving } = useSelect( ( select ) => {
		const store = select( coreStore );
		return {
			settings: store.getEditedEntityRecord( 'root', 'site' ),
			hasEdits: store.hasEditsForEntityRecord( 'root', 'site' ),
			isSaving: store.isSavingEntityRecord( 'root', 'site' ),
		};
	}, [] );

	const { editEntityRecord, saveEditedEntityRecord } =
		useDispatch( coreStore );
	const { createSuccessNotice, createErrorNotice } =
		useDispatch( noticesStore );

	const showError = useCallback(
		( message ) => createErrorNotice( message, { type: 'snackbar' } ),
		[ createErrorNotice ]
	);

	const loadStatus = useCallback( () => {
		apiFetch( { path: '/site-word-counter/v1/status' } )
			.then( setStatus )
			.catch( ( error ) => showError( error.message ) );
	}, [ showError ] );

	useEffect( loadStatus, [ loadStatus ] );

	const data = useMemo(
		() => ( {
			[ POST_TYPES ]: settings?.[ POST_TYPES ] ?? [],
			[ DISABLE_ANIMATION ]: !! settings?.[ DISABLE_ANIMATION ],
		} ),
		[ settings ]
	);

	const save = async () => {
		try {
			await saveEditedEntityRecord( 'root', 'site', undefined, {
				throwOnError: true,
			} );
			createSuccessNotice( __( 'Settings saved.', 'site-word-counter' ), {
				type: 'snackbar',
			} );
			loadStatus();
		} catch ( error ) {
			showError(
				error?.message ??
					__( 'The settings couldn’t be saved.', 'site-word-counter' )
			);
		}
	};

	const isLoading = ! settings || settings[ POST_TYPES ] === undefined;

	return (
		<ThemeProvider color={ themeColors }>
			<div className="site-word-counter-settings__root">
				<Page
					title={ __( 'Site Word Counter', 'site-word-counter' ) }
					subTitle={ __(
						'Choose which content counts toward your site’s total words, and how counters behave.',
						'site-word-counter'
					) }
					actions={
						<Button
							__next40pxDefaultSize
							variant="primary"
							isBusy={ isSaving }
							disabled={ ! hasEdits || isSaving }
							accessibleWhenDisabled
							onClick={ save }
						>
							{ __( 'Save', 'site-word-counter' ) }
						</Button>
					}
				>
					<Stack
						direction="column"
						gap="lg"
						className="site-word-counter-settings__content"
					>
						{ ! isLoading && (
							<DataForm
								data={ data }
								fields={ fields }
								form={ form }
								onChange={ ( edits ) =>
									editEntityRecord(
										'root',
										'site',
										undefined,
										edits
									)
								}
							/>
						) }
						<StatusCard
							status={ status }
							onChange={ setStatus }
							onError={ showError }
						/>
					</Stack>
				</Page>
				<Notices />
			</div>
		</ThemeProvider>
	);
}
