/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';
import { CheckboxControl } from '@wordpress/components';
import { Stack, Text } from '@wordpress/ui';

/**
 * DataForm control: a checkbox for each public post type.
 *
 * @param {Object}   props          Control props from DataForm.
 * @param {Object}   props.data     Settings being edited.
 * @param {Object}   props.field    Normalized field.
 * @param {Function} props.onChange Receives partial edits.
 */
export default function PostTypesControl( { data, field, onChange } ) {
	const selected = data[ field.id ] ?? [];

	const toggle = ( value, isChecked ) => {
		const next = isChecked
			? [ ...selected, value ]
			: selected.filter( ( slug ) => slug !== value );
		onChange( { [ field.id ]: next } );
	};

	return (
		<fieldset className="site-word-counter-settings__post-types">
			<legend>
				<Text variant="body-md">{ field.label }</Text>
			</legend>
			<Stack direction="column" gap="sm">
				{ field.elements.map( ( { value, label } ) => (
					<CheckboxControl
						key={ value }
						label={ label }
						checked={ selected.includes( value ) }
						onChange={ ( isChecked ) => toggle( value, isChecked ) }
					/>
				) ) }
			</Stack>
			<Text
				variant="body-sm"
				className="site-word-counter-settings__help"
			>
				{ selected.length === 0
					? __(
							'Pick at least one. With none picked, posts and pages count.',
							'site-word-counter'
						)
					: __(
							'Titles, drafts, and private posts never count.',
							'site-word-counter'
						) }
			</Text>
		</fieldset>
	);
}
